/**
 * Idempotent seeding helper: creates exactly 14 Indonesian-language articles
 * using the approved categories and tags requested for the Portal CMS.
 *
 * Mirrors the persistence path used by Admin\Articles::save:
 *   - ArticleModel::insert with sanitized HTML body.
 *   - category_id kept in sync as the primary (first) category.
 *   - syncCategories / syncTags populate the article_categories and
 *     article_tags pivot tables.
 *
 * Articles whose slug already exists are skipped, so re-running only fills
 * in missing records. All 14 articles are saved as published with valid local
 * cover images already placed in the media upload directory.
 */
class SeedArticles extends BaseCommand
{
    use SanitizesHtml;

